import type { Metadata } from "next";
import { SITE_NAME, SITE_TAGLINE } from "./specimens";

// The share image generated by src/app/opengraph-image.tsx.
const SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${SITE_NAME}. ${SITE_TAGLINE}.`,
  type: "image/png",
};

// A page's metadata. The canonical, og:url and twitter tags all come from one path, so they cannot
// drift apart. A page's openGraph object replaces its parent's rather than merging into it, which
// also drops the file-based share image, so the shared fields and the image are repeated here on
// purpose (measured in the build: without this, og:image was missing from every specimen page).
export function pageMetadata({
  title,
  description,
  path,
}: {
  title?: string;
  description: string;
  path: `/${string}`;
}): Metadata {
  const fullTitle = title ? `${title} · ${SITE_NAME}` : `${SITE_NAME}. ${SITE_TAGLINE}`;
  return {
    ...(title ? { title } : {}),
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: "en_GB",
      url: path,
      title: fullTitle,
      description,
      images: [SHARE_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [SHARE_IMAGE],
    },
  };
}
